<script setup lang="ts">import{computed}from 'vue';import type{FeasibilityDiagnostic}from '../types/domain';import{feasibilityLabels,dimensionLabels}from '../constants/enums';import{number}from '../utils/format';const props=defineProps<{diagnostic:FeasibilityDiagnostic;loading?:boolean;stale?:boolean}>();const tone=computed(()=>({feasible:'ok',cap_insufficient:'warn',structurally_infeasible:'bad',invalid_targets:'warn'}as const)[props.diagnostic.status]??'warn');const dimLabel=(d:string)=>dimensionLabels[d]??d;</script><template><div class="feasibility-panel" :class="tone"><div class="feas-head"><span class="badge">{{feasibilityLabels[diagnostic.status]??diagnostic.status}}</span><small v-if="stale" class="stale">输入已更新，诊断为旧结果，请重新检查</small><small v-else class="mono">指纹 / {{diagnostic.fingerprint}}</small></div><p class="feas-summary">{{diagnostic.summary}}</p><div v-if="diagnostic.status==='cap_insufficient'&&diagnostic.minimum_cap_ratio!==null" class="feas-fix"><strong>最小可行倍数</strong><b class="mono">{{number(diagnostic.minimum_cap_ratio,3)}}</b><span>当前 {{number(diagnostic.current_cap_ratio,3)}}；把截断上限提高到该倍数及以上，可行域才非空。</span></div><div v-if="diagnostic.contradictions.length" class="feas-block"><h3>矛盾类别（{{diagnostic.contradictions.length}} 组）</h3><ul><li v-for="(c,i) in diagnostic.contradictions" :key="i"><p v-if="c.categories_a.length">{{c.dimensions.map(dimLabel).join(' × ')}}：{{c.detail}}</p><p v-else>{{c.detail}}</p><small v-if="c.categories_a.length">需求 {{number(c.demand,2)}} ／ 可承载 {{number(c.capacity,2)}}</small></li></ul></div><div v-if="diagnostic.binding_categories.length" class="feas-block"><h3>最紧的目标类别</h3><table><thead><tr><th>维度</th><th>类别</th><th>支持样本</th><th>所需权重</th><th>所需倍数</th></tr></thead><tbody><tr v-for="(b,i) in diagnostic.binding_categories" :key="i"><td>{{dimLabel(b.dimension)}}</td><td>{{b.category}}</td><td>{{b.support_count}}</td><td>{{number(b.required_weight,3)}}</td><td class="mono">{{number(b.required_ratio,3)}}×</td></tr></tbody></table></div><p v-if="loading" class="feas-loading">正在求解联合可行性…</p></div></template>
